  it('rejects a list_sessions limit that is not a non-negative integer and a cursor that is malformed', () => {
    const invalid = [
      {limit: 'ten'},
      {limit: -1},
      {limit: 1.5},
      {before: 'not-an-object'},
      {before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
      {before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
      {before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {before: {updatedAt: null, sessionId: 's1'}},
    ].map(extra => validateMessage({type: 'list_sessions', ...extra}).valid);

    expect(invalid).toEqual(Array(8).fill(false));
  });
});
  return {valid: true, data: {type: 'list_sessions', limit: limit as number | undefined, before: cursor}};
}

function parseCursor(value: unknown): {updatedAt: string | number; sessionId: string} | undefined {
  if (typeof value !== 'object' || value === null) return undefined;
  const {updatedAt, sessionId} = value as Record<string, unknown>;
  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > 128) return undefined;
  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') return undefined;
  if (!Number.isFinite(new Date(updatedAt).getTime())) return undefined;
  return {updatedAt, sessionId};
}

const validators: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
  user_message: validateUserMessage,
  ping: validatePingMessage,
  list_sessions: validateListSessionsMessage,
};
}

/** The one session a store holds, for asserting what survived a close. */
export async function onlySession(store: SessionStore, sessionId: string): Promise<ChatSession | undefined> {
  return (await store.get(sessionId)) as ChatSession | undefined;
}

/** Polls until `check` holds, for at most half a second, so a teardown waits on a close without hanging on one. */
export async function eventually(check: () => boolean): Promise<void> {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
}

/** Terminates the clients, lets each server see its sockets close, then stops it, so no close is logged late. */
export async function settleAndStop(clients: WebSocket[], servers: HalServer[]): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  const stopping = servers.splice(0);
  await eventually(() => stopping.every(hal => hal.wss.clients.size === 0));
  for (const hal of stopping) await hal.stop();
}

/** A store with only the required members, so an optional one can be added, replaced or left out per test. */
export function delegatingTo(inner: InMemorySessionStore): SessionStore {
  return {
    create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
    get: sessionId => inner.get(sessionId),
    delete: sessionId => inner.delete(sessionId),
    count: () => inner.count(),
    clear: () => inner.clear(),
  };
}
